'use strict';
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(db&&(pages[next]||next==='inventory_events')&&page!==next){page=next;offset=0;render()}});
const $=s=>document.querySelector(s), fmt=n=>Number(n).toLocaleString('ko-KR',{maximumFractionDigits:2}), won=n=>`${fmt(n)} 원`, esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages={dashboard:'운영 현황',sales:'판매 기록',menus:'메뉴 수익성',profit:'기간 손익',inventory:'재료 · 재고',expenses:'비용 기록',base:'기초 자료',backup:'저장 · 백업',canvas:'화면 캔버스'};
let db,page='dashboard',start='2026-09-01',end='2026-09-18',period='월',offset=0,channel='',query='',modal=null,pendingImport=null;
const fields={sales:[['sale_id','판매 ID','text'],['date','일자','date'],['menu_id','메뉴','menu'],['channel','판매 채널','channel'],['quantity','판매 수량','number'],['unit_price','판매 당시 단가 (원)','number'],['discount_amount','할인 금액 (원)','number'],['net_sales','순매출 (원)','number'],['payment_fee','결제수수료 (원)','number'],['recipe_version','레시피 버전','text'],['unit_food_cost_snapshot','개당 식재료원가 (원)','number'],['unit_packaging_cost_snapshot','개당 포장원가 (원)','number']],expenses:[['expense_id','비용 ID','text'],['date','귀속일','date'],['category','비용 항목','category'],['amount','금액 (원)','number'],['recognition','배분 기준','text']],inventory_events:[['event_id','기록 ID','text'],['date','일자','date'],['material_id','재료','material'],['event_type','유형','event'],['quantity','증감 수량','number'],['unit','단위','unit'],['reason','사유','text'],['unit_cost','입고 단위원가 (원)','optional'],['supplier_id','공급사','supplier'],['counted_quantity','실측 수량','optional']]};
const names={sales:'판매',expenses:'비용',inventory_events:'재고'};
function selected(key){return db[key].filter(r=>r.date>=start&&r.date<=end)}
function sum(a,k){return a.reduce((s,r)=>s+Number(r[k]||0),0)}
function radar(){let rows=db.menus.map(m=>[m.name,sum(selected('sales').filter(s=>s.menu_id===m.menu_id),'quantity')]),max=Math.max(...rows.map(r=>r[1]),1);let point=(i,r)=>[100+r*Math.sin(i/8*Math.PI*2),105-r*Math.cos(i/8*Math.PI*2)];return `<div><h3>메뉴별 판매수량</h3><p class="muted">실제 판매수량 · 개</p><svg class="chart" viewBox="0 0 200 220" role="img" aria-label="메뉴별 판매수량 레이더 차트">${[20,40,60,80].map(r=>`<polygon points="${rows.map((_,i)=>point(i,r).join(',')).join(' ')}" fill="none" stroke="#929c96" stroke-width=".7"/>`).join('')}${rows.map((r,i)=>{let p=point(i,82),l=point(i,95);return `<line x1="100" y1="105" x2="${p[0]}" y2="${p[1]}" stroke="#8c9a91" stroke-width=".6"/><text x="${l[0]}" y="${l[1]}" fill="#eee" text-anchor="middle" font-size="7">${esc(r[0].slice(0,4))}</text>`}).join('')}<polygon points="${rows.map((r,i)=>point(i,r[1]/max*80).join(',')).join(' ')}" fill="#0c707255" stroke="#73b8b6" stroke-width="2"/></svg></div>`}
function menuName(id){return db.menus.find(m=>m.menu_id===id)?.name||id}function materialName(id){return db.materials.find(m=>m.material_id===id)?.name||id}
function costs(a){return a.reduce((s,r)=>s+r.quantity*(r.unit_food_cost_snapshot+r.unit_packaging_cost_snapshot),0)}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3000)}
function persist(){try{localStorage.setItem('prep-cafe-v1',JSON.stringify(db));return true}catch{toast('저장 공간이 부족합니다. 백업을 내려받아 주세요.');return false}}
function navigate(p){page=p;offset=0;query='';channel='';location.hash=p;render()}
function periodUI(){return `<div class="toolbar"><div class="filters"><select id="period" aria-label="조회 단위">${['일','주','월','분기','반기','연간'].map(x=>`<option ${period===x?'selected':''}>${x}</option>`).join('')}</select><input aria-label="조회 시작일" id="start" type="date" value="${start}"><span>~</span><input aria-label="조회 종료일" id="end" type="date" value="${end}"><button id="apply" class="primary">조회</button></div><span class="muted">실제 기록 기간 · ${start.replaceAll('-','.')} – ${end.replaceAll('-','.')}</span></div>`}
function notice(s,w=false){return `<div class="notice ${w?'warn':''}">${s}</div>`}
function summary(){let sales=selected('sales'),exp=selected('expenses'),ev=selected('inventory_events');return `<section class="summary"><h2>Total Overview <span class="subtle">· 실제 실적</span></h2><div class="kpis">${[['총 판매수량',`${fmt(sum(sales,'quantity'))} 개`],['순매출',won(sum(sales,'net_sales'))],['비용 기록',won(sum(exp,'amount'))],['입고 기록',`${ev.filter(x=>x.event_type==='입고').length} 건`],['마감 기준일','2026.09.18']].map(([l,v])=>`<div class="kpi"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div></section>`}
function legend(items){return `<div class="legend">${items.map(([l,c])=>`<span><i style="background:${c}"></i>${l}</span>`).join('')}</div>`}
function chart(a,b,labels){let max=Math.max(...a,...b,1),W=800,H=225,base=185,step=720/Math.max(a.length,1);let s='<svg class="chart" viewBox="0 0 800 225" role="img" aria-label="기간별 실제 기록 차트">';[0,.25,.5,.75,1].forEach(f=>{let y=base-f*145;s+=`<line x1="55" y1="${y}" x2="785" y2="${y}" stroke="#747b77" stroke-opacity=".25"/><text x="48" y="${y+4}" text-anchor="end" fill="#d0d6d3" font-size="10">${fmt(Math.round(max*f/1000))}천</text>`});a.forEach((v,i)=>{let x=62+i*step,h=v/max*145;s+=`<rect x="${x}" y="${base-h}" width="${step*.32}" height="${h}" fill="#4a8d8c"/><text x="${x+step*.3}" y="204" fill="#f3f5f4" text-anchor="middle" font-size="10">${esc(labels[i])}</text>`});let pts=b.map((v,i)=>`${62+i*step+step*.3},${base-v/max*145}`);s+=`<polyline points="${pts.join(' ')}" fill="none" stroke="#ff7c82" stroke-width="2.4"/>`;pts.forEach(p=>{let [x,y]=p.split(',');s+=`<circle cx="${x}" cy="${y}" r="3" fill="#ff7c82"/>`});return s+'</svg>'}
function monthly(){let keys=[...new Set(db.calendar.filter(r=>r.date>=start&&r.date<=end).map(r=>r.date.slice(0,7)))];if(keys.length===1){keys=[...new Set(selected('sales').map(r=>r.date))].slice(-18);return {labels:keys.map(x=>x.slice(8)+'일'),a:keys.map(k=>sum(db.sales.filter(r=>r.date===k),'net_sales')),b:keys.map(k=>sum(db.expenses.filter(r=>r.date===k),'amount'))}}return {labels:keys.map(x=>x.slice(2).replace('-','.')),a:keys.map(k=>sum(selected('sales').filter(r=>r.date.startsWith(k)),'net_sales')),b:keys.map(k=>sum(selected('expenses').filter(r=>r.date.startsWith(k)),'amount'))}}
function donut(rows,title){const colors=['#0c7072','#4b9494','#7bb5b4','#c2dede','#e8f1f1','#a7cecd','#659f9f','#d9e9e9'];let total=rows.reduce((s,r)=>s+r[1],0)||1,acc=0;return `<div><h3>${title}</h3><p class="muted">선택 기간의 실제 기록을 확인합니다.</p><div class="donut"><svg viewBox="0 0 200 200" role="img" aria-label="${title}">${rows.map(([name,v],i)=>{let f=v/total,ang=acc*2*Math.PI-Math.PI/2;acc+=f;let endAng=acc*2*Math.PI-Math.PI/2;return `<path d="M100 100 L${100+87*Math.cos(ang)} ${100+87*Math.sin(ang)} A87 87 0 ${f>.5?1:0} 1 ${100+87*Math.cos(endAng)} ${100+87*Math.sin(endAng)} Z" fill="${colors[i]}" stroke="#edf3f2" stroke-width="1.5"><title>${esc(name)} ${fmt(f*100)}%</title></path>`}).join('')}<circle cx="100" cy="100" r="36" fill="#3d3e3d"/><text x="100" y="99" text-anchor="middle" fill="white" font-size="12">실제 기록</text><text x="100" y="116" text-anchor="middle" fill="#c2dede" font-size="10">${rows.length} 항목</text></svg>${legend(rows.map((r,i)=>[r[0],colors[i]]))}</div></div>`}
function dashboard(){let c=monthly(),sales=selected('sales'),exp=selected('expenses');let sold=db.menus.map(m=>[m.name,sum(sales.filter(r=>r.menu_id===m.menu_id),'quantity')]).sort((a,b)=>b[1]-a[1]);let expenses=[...new Set(exp.map(x=>x.category))].map(k=>[k,sum(exp.filter(x=>x.category===k),'amount')]);return `${summary()}${periodUI()}<div class="dashboard"><aside class="sidebar"><div class="side-card"><h3>① 메뉴별 판매수량</h3>${sold.slice(0,5).map(r=>`<div class="side-row"><span>${r[0]}</span><strong>${fmt(r[1])} 개</strong></div>`).join('')}</div><div class="side-card"><h3>② 재고 기록 현황</h3>${['입고','폐기','실사조정'].map(k=>`<div class="side-row"><span>${k}</span><strong>${selected('inventory_events').filter(e=>e.event_type===k).length} 건</strong></div>`).join('')}<div class="side-row"><span>재료 종류</span><strong>11 종</strong></div><div class="side-row"><span>발주 기준</span><strong>설정 필요</strong></div></div></aside><section class="chart-panel"><div class="chart-header"><div><h3>전체 기간별 현황</h3><span class="muted">순매출과 비용 기록을 확인합니다. 금액 단위: 천 원</span></div>${legend([['순매출','#4a8d8c'],['비용','#ff7c82']])}</div>${chart(c.a,c.b,c.labels)}<div class="lower"><div><h3>메뉴별 판매 실적</h3><p class="muted">메뉴별 순매출과 판매 당시 직접비용 기록 · 천 원</p>${chart(db.menus.map(m=>sum(sales.filter(r=>r.menu_id===m.menu_id),'net_sales')),db.menus.map(m=>costs(sales.filter(r=>r.menu_id===m.menu_id))),db.menus.map(m=>m.name.slice(0,4)))}</div>${radar()}${donut(sold,'① 메뉴 판매 구성')}${donut(expenses,'② 비용 항목 구성')}</div></section></div>${notice('메뉴 수익성, 최종 손익, 예상 손익, 발주 참고량은 계산 기준 결정 후 제공됩니다. 현재는 실제 기록만 표시합니다.')}<div class="actions"><button data-page="sales" class="primary">판매 기록 입력</button><button data-page="menus">메뉴 수익성 확인 →</button><button data-page="profit">기간 손익 →</button><button data-page="inventory">재료 잔량 →</button></div>`}
function recordPage(key){let rows=selected(key).filter(r=>(!channel||r.channel===channel)&&(!query||JSON.stringify(r).includes(query)||menuName(r.menu_id||'').includes(query)||materialName(r.material_id||'').includes(query)));let list=rows.slice(offset,offset+20),cols=key==='sales'?['date','menu_id','channel','quantity','net_sales','payment_fee']:key==='expenses'?['date','category','amount','recognition']:['date','material_id','event_type','quantity','unit','counted_quantity'];return `<h2>${names[key]} 기록</h2><span class="muted">기록을 입력하고 수정·삭제합니다. ${key==='sales'?'주문별 내역이 아닌 일자·메뉴·채널별 집계입니다.':''}</span>${periodUI()}<div class="toolbar"><div class="filters"><input id="search" value="${esc(query)}" placeholder="${key==='sales'?'메뉴명 또는 ID':key==='expenses'?'비용 항목 또는 ID':'재료명 또는 ID'}" aria-label="기록 검색">${key==='sales'?`<select id="channel"><option value="">전체 채널</option>${['매장','포장'].map(x=>`<option ${channel===x?'selected':''}>${x}</option>`).join('')}</select>`:''}<span class="muted">${fmt(rows.length)} 건</span></div><div class="actions">${key!=='inventory_events'?`<button data-template="${key}">↓ 엑셀 양식</button><button data-import="${key}">↑ 엑셀 가져오기</button>`:''}<button class="primary" data-add="${key}">＋ ${names[key]} 기록 입력</button></div></div>${key==='expenses'?notice('일자별 비용 기록만 실제 비용으로 표시합니다. 월 비용 계획은 별도 계획 자료이며 이중 합산하지 않습니다.'):key==='inventory_events'?notice('폐기는 음수, 입고는 양수입니다. 실사조정은 기존 자료의 증감 기록을 보존합니다. 새 실사 기록은 정책 결정 전 실제 수량만 보관합니다.') :''}<div class="table-wrap"><table><thead><tr>${cols.map(c=>`<th>${fields[key].find(x=>x[0]===c)?.[1]||c}</th>`).join('')}<th>관리</th></tr></thead><tbody>${list.map(r=>`<tr>${cols.map(c=>`<td class="${typeof r[c]==='number'?'num':''}">${c==='menu_id'?esc(menuName(r[c])):c==='material_id'?esc(materialName(r[c])):r[c]===undefined?'—':typeof r[c]==='number'?fmt(r[c]):esc(r[c])}</td>`).join('')}<td><button data-edit="${key}|${r[fields[key][0][0]]}">수정</button><button class="danger" data-delete="${key}|${r[fields[key][0][0]]}">삭제</button></td></tr>`).join('')||`<tr><td colspan="${cols.length+1}" class="empty">조회 기간에 등록된 기록이 없습니다.</td></tr>`}</tbody></table></div><div class="pager"><button id="prev" ${offset===0?'disabled':''}>이전</button><span>${rows.length?Math.floor(offset/20)+1:0} / ${Math.ceil(rows.length/20)}</span><button id="next" ${offset+20>=rows.length?'disabled':''}>다음</button></div>`}
function table(headers,rows){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function menus(){let a=selected('sales');return `<h2>메뉴별 수익성</h2><span class="muted">판매 실적과 당시 원가 기록을 함께 확인합니다.</span>${periodUI()}${notice('수익성 기준 결정 대기 · 임차료와 인건비를 메뉴에 배분할지 아직 정하지 않았습니다. 수익성 결과를 임의로 계산하지 않습니다.',true)}${table(['메뉴','판매수량','순매출','식재료 · 포장 비용 기록','결제수수료','수익성'],db.menus.map(m=>{let s=a.filter(x=>x.menu_id===m.menu_id);return [m.name,fmt(sum(s,'quantity'))+' 개',won(sum(s,'net_sales')),won(costs(s)),won(sum(s,'payment_fee')),'<span class="pill pending">기준 설정 필요</span>']}))}<div class="toolbar"><button data-page="sales">← 판매 기록</button><button data-page="profit" class="primary">기간 손익 확인 →</button></div>`}
function profit(){let a=selected('sales'),b=selected('expenses'),c=monthly(),future=db.calendar.filter(x=>x.date>=start&&x.date<=end&&!x.record_complete);return `<h2>기간 실적 및 예상 손익</h2><span class="muted">실제 실적과 미마감 기간의 예상값을 구분합니다.</span>${periodUI()}<div class="stat-grid"><div class="stat"><span class="pill">실제 실적</span><p>순매출</p><strong>${won(sum(a,'net_sales'))}</strong></div><div class="stat"><span class="pill">실제 비용 기록</span><p>운영 비용</p><strong>${won(sum(b,'amount'))}</strong></div><div class="stat"><span class="pill pending">예상값</span><p>예상 손익</p><strong class="pending-value">기준 설정 필요</strong></div></div>${notice(`자료 마감은 2026.09.18입니다. 선택 기간 내 미마감 날짜 ${future.length}일은 실제 판매 0으로 집계하지 않습니다. 연간 조회는 전체 연도 실적이 아닌 포함 기간의 실적입니다.`)}<div class="chart-header"><h3>기간별 실제 매출 · 비용</h3>${legend([['순매출','#4a8d8c'],['비용','#ff7c82']])}</div>${chart(c.a,c.b,c.labels)}<div class="panel-grid"><section class="panel"><h3>실제 기록 구성</h3>${table(['항목','금액'],[['순매출',won(sum(a,'net_sales'))],['판매 당시 식재료 · 포장비',won(costs(a))],['결제수수료',won(sum(a,'payment_fee'))],['운영 비용 기록',won(sum(b,'amount'))],['최종 손익','<span class="pill pending">비용 포함 범위 설정 필요</span>']])}</section><section class="panel"><h3>예상 손익</h3><span class="pill pending">결정 대기</span><p>예상 기준 기간과 방법을 정하면 예상값을 확인할 수 있습니다.</p><p class="muted">월 비용 계획은 기초 자료에서 조회할 수 있으며 실제 비용에 합산하지 않습니다.</p></section></div><div class="toolbar"><button data-page="menus">← 메뉴 수익성</button><button class="primary" data-page="inventory">재료 잔량 확인 →</button></div>`}
function balances(){let result={};db.opening_inventory.forEach(x=>result[x.material_id]=x.quantity);db.inventory_events.filter(e=>e.date<=end&&!e.ui_count_only).forEach(e=>result[e.material_id]=(result[e.material_id]||0)+e.quantity);db.sales.filter(s=>s.date<=end).forEach(s=>db.recipes.filter(r=>r.menu_id===s.menu_id&&r.recipe_version===s.recipe_version&&(!r.channel_only||r.channel_only===s.channel)).forEach(r=>result[r.material_id]-=s.quantity*r.quantity));return result}
function inventory(){let b=balances();return `<h2>재료 잔량 및 발주 참고</h2><span class="muted">재료별 수량은 g · ml · 개 단위로 구분합니다.</span>${periodUI()}${notice('계산상 잔량은 제공된 초기재고·판매 사용량·증감 기록을 그대로 연결한 참고값입니다. 실제 재고는 실측일의 기록이며 현재 재고로 간주하지 않습니다.')}<div class="toolbar"><span class="pill">기준일 ${end}</span><button class="primary" data-add="inventory_events">＋ 입고 · 폐기 · 실제 재고 기록</button></div>${table(['재료','계산상 잔량','마지막 실측 수량','실측일','납기 / 안전재고','부족 여부 · 발주 참고량'],db.materials.map(m=>{let counts=db.inventory_events.filter(x=>x.material_id===m.material_id&&x.date<=end&&x.counted_quantity!=null).sort((a,b)=>a.date.localeCompare(b.date));let last=counts.at(-1);return [m.name,`${fmt(b[m.material_id])} ${m.unit}`,last?`${fmt(last.counted_quantity)} ${m.unit}`:'실측 기록 없음',last?.date||'—',`${m.lead_days} / ${m.safety_days} 영업일`,'<span class="pill pending">판단 기준 설정 필요</span>']}))}${notice('실제 재고 입력의 반영 방식과 발주 판단 기준은 결정 대기입니다. 발주 참고량은 자동 발주나 확정 주문이 아닙니다.',true)}<h3>입고 · 폐기 · 실사 기록</h3><button data-page="inventory_events">재고 기록 관리 →</button>`}
let baseTab='menus';function base(){const cols={menus:['menu_id','name','price','category','recipe_version'],materials:['material_id','name','unit','pack_quantity','base_pack_price','lead_days','safety_days'],recipes:['recipe_version','menu_id','material_id','quantity','unit','channel_only'],price_history:['material_id','effective_date','pack_price','pack_quantity'],suppliers:['supplier_id','name'],calendar:['date','is_open','record_complete','weather','note'],monthly_expense_plan:['month','category','amount']},labels={menus:'메뉴',materials:'재료',recipes:'레시피',price_history:'가격 이력',suppliers:'공급사',calendar:'영업 달력',monthly_expense_plan:'월 비용 계획'};const h={menu_id:'메뉴 ID',name:'이름',price:'판매 기준가 (원)',category:'분류',recipe_version:'레시피 버전',material_id:'재료 ID',unit:'단위',pack_quantity:'구매용량',base_pack_price:'최초 가격 (원)',lead_days:'납기 (영업일)',safety_days:'안전재고 (영업일)',quantity:'개당 사용량',channel_only:'적용 채널',effective_date:'적용 시작일',pack_price:'구매가격 (원)',supplier_id:'공급사 ID',date:'일자',is_open:'영업 여부',record_complete:'마감 여부',weather:'날씨',note:'메모',month:'귀속월',amount:'월금액 (원)'};let rows=db[baseTab];if(baseTab==='calendar')rows=rows.filter(r=>r.date>=start&&r.date<=end);return `<h2>기초 자료</h2><span class="muted">제공된 기초 자료를 읽기 전용으로 확인합니다.</span><div class="tabs">${Object.entries(labels).map(([k,v])=>`<button data-base="${k}" class="${baseTab===k?'active':''}">${v}</button>`).join('')}</div>${baseTab==='calendar'?periodUI():''}${table(cols[baseTab].map(c=>h[c]),rows.map(r=>cols[baseTab].map(c=>r[c]===undefined?'전체 채널':typeof r[c]==='boolean'?r[c]?'예':'아니오':typeof r[c]==='number'?fmt(r[c]):esc(r[c]))))}`}
function backup(){return `<h2>저장 · 백업 · 복원</h2><span class="muted">이 브라우저에 저장된 기록과 기초 자료를 함께 관리합니다.</span>${notice('이 시제품의 저장은 현재 브라우저에서 동작합니다. 다른 기기로 옮기거나 보관하려면 백업 파일을 내려받으세요. 저장·배포 정책은 제품 결정 대기입니다.')}<div class="panel-grid"><section class="panel"><h3>현재 저장 데이터</h3><span class="pill saved">브라우저 저장</span><div class="backup-meta">${[['판매 기록',db.sales.length],['비용 기록',db.expenses.length],['재고 기록',db.inventory_events.length],['메뉴 / 재료',`${db.menus.length} / ${db.materials.length}`]].map(([l,v])=>`<div><span class="muted">${l}</span><strong>${typeof v==='number'?fmt(v):v}${typeof v==='number'?' 건':''}</strong></div>`).join('')}</div><button class="primary" id="save">지금 저장</button></section><section class="panel"><h3>전체 백업</h3><p>기초 자료와 판매·비용·재고 기록을 한 파일로 보관합니다.</p><button class="primary" id="backup">↓ 백업 내려받기</button><hr><h3>백업 복원</h3><p>복원할 기록을 검토한 뒤 현재 자료를 교체합니다.</p><button id="restore">↑ 백업 파일 선택</button></section></div>`}
function canvas(){let screens=[['dashboard','운영 현황'],['sales','판매 기록'],['menus','메뉴 수익성'],['profit','기간 손익'],['inventory','재료 잔량'],['inventory_events','재고 기록'],['expenses','비용 기록'],['base','기초 자료'],['backup','저장 · 백업']];return `<h2>화면 캔버스</h2><p class="muted">페이지와 팝업이 열린 화면을 개별적으로 확인합니다. 예시 상태는 실제 데이터를 변경하지 않습니다.</p><div class="state-grid">${screens.map(([p,l])=>`<section class="state-card"><h3>${l}</h3><p class="muted">${p==='menus'||p==='profit'||p==='inventory'?'실제 기록 · 기준 결정 대기':'기본 화면'}</p><button data-page="${p}">화면 보기 →</button></section>`).join('')}${['sales','expenses','inventory_events'].map(k=>`<section class="state-card"><h3>${names[k]} 기록 팝업</h3><p class="muted">입력 · 수정 · 삭제 · 오류 상태</p><button data-preview="${k}|add">입력</button><button data-preview="${k}|edit">수정</button><button data-preview="${k}|delete">삭제 확인</button><button data-preview="${k}|error">입력 오류</button></section>`).join('')}<section class="state-card"><h3>엑셀 가져오기 팝업</h3><p class="muted">파일 선택 · 검토 · 오류 · 중복</p><button data-import="sales">파일 선택</button><button data-state="importReview">가져오기 검토</button><button data-state="importError">파일 오류</button><button data-state="duplicate">중복 확인</button></section><section class="state-card"><h3>백업 복원 팝업</h3><p class="muted">파일 선택 · 교체 확인 · 오류</p><button id="restore">파일 선택</button><button data-state="restoreConfirm">복원 확인</button><button data-state="restoreError">복원 오류</button></section><section class="state-card"><h3>기록 상태</h3><p class="muted">빈 기록 · 로딩 · 저장 완료</p><button data-state="empty">빈 기록</button><button data-state="loading">로딩</button><button data-state="saved">저장 완료</button></section></div>`}
function render(){if(!db)return;$('#nav').innerHTML=Object.entries(pages).map(([p,l])=>`<button data-page="${p}" class="${page===p?'active':''}">${l}</button>`).join('');$('#app').innerHTML=page==='dashboard'?dashboard():page==='sales'||page==='expenses'||page==='inventory_events'?recordPage(page):page==='menus'?menus():page==='profit'?profit():page==='inventory'?inventory():page==='base'?base():page==='backup'?backup():canvas();bind();}
function bind(){document.querySelectorAll('[data-page]').forEach(el=>el.onclick=()=>navigate(el.dataset.page));document.querySelectorAll('[data-add]').forEach(el=>el.onclick=()=>recordModal(el.dataset.add));document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>recordModal(...el.dataset.edit.split('|')));document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>deleteModal(...el.dataset.delete.split('|')));document.querySelectorAll('[data-template]').forEach(el=>el.onclick=()=>template(el.dataset.template));document.querySelectorAll('[data-import]').forEach(el=>el.onclick=()=>importModal(el.dataset.import));document.querySelectorAll('[data-base]').forEach(el=>el.onclick=()=>{baseTab=el.dataset.base;render()});document.querySelectorAll('[data-preview]').forEach(el=>el.onclick=()=>{let [k,mode]=el.dataset.preview.split('|');navigate(k);if(mode==='delete')deleteModal(k,db[k][0][fields[k][0][0]],true);else recordModal(k,mode==='edit'?db[k][0][fields[k][0][0]]:null,true,mode==='error')});document.querySelectorAll('[data-state]').forEach(el=>el.onclick=()=>stateModal(el.dataset.state));if($('#apply'))$('#apply').onclick=()=>{if($('#start').value>$('#end').value)return toast('시작일은 종료일보다 늦을 수 없습니다.');start=$('#start').value;end=$('#end').value;period=$('#period').value;offset=0;render()};if($('#period'))$('#period').onchange=()=>{const p=$('#period').value;period=p;let d=$('#end').value||end,dt=new Date(d+'T00:00:00Z');if(p==='일')$('#start').value=d;else if(p==='주'){dt.setUTCDate(dt.getUTCDate()-6);$('#start').value=dt.toISOString().slice(0,10)}else {let mo=Number(d.slice(5,7));let m=p==='월'?mo:p==='분기'?Math.floor((mo-1)/3)*3+1:p==='반기'?mo<=6?1:7:1;$('#start').value=`${d.slice(0,4)}-${String(m).padStart(2,'0')}-01`} };if($('#search'))$('#search').onchange=e=>{query=e.target.value;offset=0;render()};if($('#channel'))$('#channel').onchange=e=>{channel=e.target.value;offset=0;render()};if($('#prev'))$('#prev').onclick=()=>{offset=Math.max(0,offset-20);render()};if($('#next'))$('#next').onclick=()=>{offset+=20;render()};if($('#backup'))$('#backup').onclick=()=>download('prep-cafe-backup.json',JSON.stringify({schema:'prep-cafe-backup-v1',data:db},null,2),'application/json');if($('#save'))$('#save').onclick=()=>{if(persist())toast('현재 기록을 저장했습니다.')};if($('#restore'))$('#restore').onclick=restoreModal;}
function showModal(title,body,actions=''){modal=document.activeElement;$('#overlay').innerHTML=`<div class="backdrop"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button class="close" aria-label="닫기">×</button></div>${body}<div class="modal-actions">${actions||'<button class="primary" data-close>확인</button>'}</div></section></div>`;$('#overlay .close').onclick=closeModal;document.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);$('#overlay').querySelector('input,button').focus()}
function closeModal(){$('#overlay').innerHTML='';modal?.focus()}
document.addEventListener('keydown',e=>{if(!$('#overlay').innerHTML)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){let a=[...$('#overlay').querySelectorAll('button,input,select')].filter(x=>!x.disabled),first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function opts(type){if(type==='menu')return db.menus.map(m=>[m.menu_id,m.name]);if(type==='material')return db.materials.map(m=>[m.material_id,`${m.name} (${m.unit})`]);if(type==='supplier')return [['','해당 없음'],...db.suppliers.map(m=>[m.supplier_id,m.name])];const a={channel:['매장','포장'],category:[...new Set(db.expenses.map(x=>x.category))],event:['입고','폐기','실사조정'],unit:['g','ml','개']};return a[type]?.map(x=>[x,x])}
function recordModal(key,id=null,preview=false,error=false){let idkey=fields[key][0][0],original=id?db[key].find(r=>r[idkey]===id):null;let values=original||{[idkey]:'UI'+Date.now(),date:end,recipe_version:'R1',recognition:'직접 입력',channel:'매장',event_type:'입고',unit:'g'};showModal(`${names[key]} 기록 ${id?'수정':'입력'}${preview?' · 화면 예시':''}`,`${key==='sales'?notice('당시 단가·할인·순매출·수수료·개당 원가를 기록합니다. 미정 계산 기준을 자동 적용하지 않습니다.'):''}<form id="recordForm"><div class="form-grid">${fields[key].map(([k,l,t])=>{let o=opts(t),v=values[k]??'';return `<label class="field">${l}<${o?'select':'input'} name="${k}" ${!o?`type="${t==='optional'?'number':t}" ${['number','optional'].includes(t)?'step="any"':''} value="${esc(v)}"`:''} ${id&&k===idkey?'readonly':''}>${o?o.map(([a,b])=>`<option value="${a}" ${a===v?'selected':''}>${b}</option>`).join('')+'</select>':''}</label>`}).join('')}</div><div id="formError" class="error" role="alert">${error?'판매수량을 입력해 주세요. 빈칸은 0과 다릅니다.':''}</div></form>`, '<button data-close>취소</button><button id="recordSave" class="primary">저장</button>');if(key==='inventory_events')noticeInventory();$('#recordSave').onclick=()=>{const f=new FormData($('#recordForm')),r={};for(const [k,l,t]of fields[key]){let v=f.get(k);if((v===null||v==='')&&t!=='optional'&&t!=='supplier'&&k!=='reason')return $('#formError').textContent=`${l}을(를) 입력해 주세요.`;r[k]=['number','optional'].includes(t)?v===''?undefined:Number(v):v;}let err=validate(key,r,id);if(err)return $('#formError').textContent=err;if(preview){closeModal();return toast('화면 예시입니다. 실제 기록은 변경하지 않았습니다.')}if(key==='inventory_events'&&r.event_type==='실사조정'&&!original){r.quantity=0;r.ui_count_only=true;}if(original)db[key][db[key].indexOf(original)]=r;else db[key].push(r);persist();closeModal();render();toast('기록을 저장했습니다.')};}
function noticeInventory(){let f=$('#recordForm');f.insertAdjacentHTML('afterbegin',notice('새 실사는 실측 수량만 보관합니다. 계산상 재고 반영은 정책 결정 대기입니다.'));f.elements.material_id.onchange=()=>{f.elements.unit.value=db.materials.find(m=>m.material_id===f.elements.material_id.value).unit};f.elements.event_type.onchange=()=>{if(f.elements.event_type.value==='실사조정'){f.elements.quantity.value=0}}}
function validate(key,r,id){let k=fields[key][0][0];if(db[key].some(x=>x[k]===r[k]&&x[k]!==id))return '같은 ID의 기록이 이미 있습니다. 중복 처리 정책이 정해질 때까지 변경하지 않습니다.';if(!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||Number.isNaN(Date.parse(r.date)))return '날짜를 확인해 주세요.';if(fields[key].some(([k,l,t])=>['number','optional'].includes(t)&&r[k]!==undefined&&!Number.isFinite(r[k])))return '숫자 항목을 확인해 주세요.';if(key==='sales'){if(!db.menus.some(m=>m.menu_id===r.menu_id))return '알 수 없는 메뉴 ID입니다.';if(r.quantity<0||r.net_sales<0||r.unit_price<0)return '판매수량과 금액은 음수일 수 없습니다.';if(db.calendar.some(c=>c.date===r.date&&!c.record_complete))return '미마감 날짜입니다. 마감 정책 결정 전에는 확정 판매를 입력할 수 없습니다.';if(db.sales.some(x=>x.date===r.date&&x.menu_id===r.menu_id&&x.channel===r.channel&&x.sale_id!==id))return '동일 일자·메뉴·채널의 판매 기록이 있습니다. 기존 기록을 수정해 주세요.';}if(key==='expenses'&&r.amount<0)return '비용 금액을 확인해 주세요.';if(key==='inventory_events'){let m=db.materials.find(m=>m.material_id===r.material_id);if(!m)return '알 수 없는 재료 ID입니다.';if(m.unit!==r.unit)return '재료의 기준단위가 일치하지 않습니다.';if(r.event_type==='입고'&&r.quantity<=0)return '입고 수량은 양수로 입력해 주세요.';if(r.event_type==='폐기'&&r.quantity>=0)return '폐기 수량은 음수로 입력해 주세요.';if(r.event_type==='실사조정'&&(r.counted_quantity==null||r.counted_quantity<0))return '실측 수량을 입력해 주세요.';}return ''}
function deleteModal(key,id,preview=false){showModal(`${names[key]} 기록 삭제`, `<p>기록 <strong>${esc(id)}</strong>을 삭제할까요?</p>${notice('삭제하면 관련 실제 실적과 계산상 재고에도 반영됩니다.',true)}`,'<button data-close>취소</button><button class="danger" id="confirmDelete">삭제</button>');$('#confirmDelete').onclick=()=>{if(!preview){db[key]=db[key].filter(r=>r[fields[key][0][0]]!==id);persist()}closeModal();render();toast(preview?'화면 예시입니다. 실제 기록은 삭제하지 않았습니다.':'기록을 삭제했습니다.')}}
function download(name,content,type){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function template(key){let wb=XLSX.utils.book_new(),cols=fields[key].map(f=>f[1]);XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([cols]),names[key]+'기록');XLSX.writeFile(wb,`프렙_${names[key]}기록_양식.xlsx`);toast('엑셀 양식을 내려받았습니다.')}
function importModal(key){showModal(`${names[key]} 엑셀 가져오기`,`${notice('내려받은 양식의 열 이름을 유지해 주세요. 엑셀과 JSON은 같은 자료이므로 중복으로 입력하지 않습니다.')}<div class="drop">작성한 엑셀 파일을 선택해 주세요.<br><small>.xlsx · .xls</small><input id="importFile" type="file" accept=".xlsx,.xls" aria-label="엑셀 파일 선택"></div><div id="importMessage" role="alert"></div>`,'<button data-close>취소</button>');$('#importFile').onchange=async e=>{try{let file=e.target.files[0];if(!file)return;let wb=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:true}),a=XLSX.utils.sheet_to_json(wb.Sheets[wb.SheetNames[0]],{header:1,defval:null});let headers=fields[key].map(x=>x[1]);if(!headers.every((h,i)=>a[0]?.[i]===h))throw Error('열 이름이 양식과 다릅니다. 제공 양식을 사용해 주세요.');let rows=a.slice(1).filter(r=>r.some(v=>v!==null)).map(row=>Object.fromEntries(fields[key].map(([k,l,t],i)=>{let v=row[i];if(v instanceof Date)v=v.toISOString().slice(0,10);return [k,v===null?undefined:['number','optional'].includes(t)?Number(v):String(v)]})));if(!rows.length)throw Error('가져올 기록이 없습니다.');let errors=[],ids=new Set();rows.forEach((r,i)=>{let required=fields[key].find(([k,l,t])=>r[k]===undefined&&!['optional','supplier'].includes(t)&&k!=='reason');let err=required?required[1]+' 값이 비어 있습니다.':validate(key,r);let id=r[fields[key][0][0]];if(ids.has(id))err='파일 안에 동일 ID가 중복되어 있습니다.';ids.add(id);if(err)errors.push(`${i+2}행: ${err}`)});if(errors.length)throw Error(errors.slice(0,10).join('\n'));pendingImport={key,rows};showModal('가져오기 검토',`<p>${esc(file.name)}</p><p>검사를 통과한 <strong>${rows.length}건</strong>을 가져옵니다.</p>${notice('기존 기록은 유지됩니다. 중복된 기록이 있는 파일은 적용하지 않습니다.')}<div class="review">${table(headers.slice(0,4),rows.slice(0,5).map(r=>fields[key].slice(0,4).map(f=>esc(r[f[0]]))))}</div>`,'<button data-close>취소</button><button id="confirmImport" class="primary">가져오기</button>');$('#confirmImport').onclick=()=>{db[key].push(...rows);persist();pendingImport=null;closeModal();render();toast(`${rows.length}건을 가져왔습니다.`)}}catch(err){$('#importMessage').innerHTML=notice(esc(err.message).replaceAll('\n','<br>'),true)}}}
function validBackup(o){let d=o?.data;if(o?.schema!=='prep-cafe-backup-v1'||!d?.meta||!d.settings)return false;for(let key of ['sales','expenses','inventory_events','menus','materials','recipes','calendar','opening_inventory','suppliers','price_history','monthly_expense_plan'])if(!Array.isArray(d[key]))return false;for(let key of ['sales','expenses','inventory_events']){let ids=new Set();for(let r of d[key]){if(!fields[key].every(([k,l,t])=>['optional','supplier'].includes(t)||k==='reason'||r[k]!=null)||!r.date||ids.has(r[fields[key][0][0]]))return false;ids.add(r[fields[key][0][0]]);}}return true}
function restoreModal(){showModal('백업 파일 선택','<div class="drop">전체 기록 백업 파일을 선택해 주세요.<input id="restoreFile" type="file" accept=".json" aria-label="백업 파일 선택"></div><div id="restoreError" role="alert"></div>','<button data-close>취소</button>');$('#restoreFile').onchange=async e=>{try{let o=JSON.parse(await e.target.files[0].text());if(!validBackup(o))throw Error('복원할 수 없는 백업 형식이거나 기록이 손상되었습니다.');showModal('백업 복원 확인',`<p>판매 ${fmt(o.data.sales.length)}건 · 비용 ${fmt(o.data.expenses.length)}건 · 재고 ${fmt(o.data.inventory_events.length)}건</p>${notice('현재 기록을 백업의 기록으로 교체합니다. 현재 자료의 백업을 먼저 내려받을 수 있습니다.',true)}`,'<button id="beforeBackup">현재 자료 백업</button><button data-close>취소</button><button id="confirmRestore" class="primary">복원</button>');$('#beforeBackup').onclick=()=>download('prep-cafe-before-restore.json',JSON.stringify({schema:'prep-cafe-backup-v1',data:db}),'application/json');$('#confirmRestore').onclick=()=>{let old=db;db=o.data;if(!persist()){db=old;return}closeModal();render();toast('전체 기록을 복원했습니다.')}}catch(err){$('#restoreError').innerHTML=notice(esc(err.message),true)}}}
function stateModal(s){const states={empty:['기록 없음','<div class="empty">조회 기간에 등록된 기록이 없습니다.</div>'],loading:['자료 불러오기','<div class="loading">매장 기록을 불러오는 중입니다…</div>'],saved:['저장 완료','<p class="saved">기록을 저장했습니다.</p>'],importReview:['가져오기 검토','<p>판매 기록 3건 · 형식 검사 완료</p>'+notice('화면 예시입니다. 실제 기록은 적용하지 않습니다.')],importError:['엑셀 파일 오류',notice('3행: 판매수량이 비어 있습니다.<br>5행: 알 수 없는 메뉴 ID입니다.<br>기존 기록은 변경되지 않았습니다.',true)],duplicate:['중복 기록 확인',notice('S000001은 이미 등록된 기록입니다.<br>중복 처리 정책 결정 전에는 해당 파일을 적용하지 않습니다.',true)],restoreConfirm:['백업 복원 확인','<p>판매 6,112건 · 비용 3,560건 · 재고 1,515건</p>'+notice('현재 자료를 백업 기록으로 교체합니다. 화면 예시에서는 데이터를 변경하지 않습니다.',true)],restoreError:['백업 복원 오류',notice('복원할 수 없는 백업 형식입니다. 기존 자료는 보존되었습니다.',true)]};showModal(...states[s])}
